Testing with Jasmine & Karma

Angular | Lesson 15

Learning Objectives

Write tests with Jasmine and Karma\nUse TestBed for testing module configuration\nUse ComponentFixture for component testing\nUse describe/it/expect for test structure

--Program: Angular

typescript
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { AppComponent } from './app.component';

describe('AppComponent', () => {
  let component: AppComponent;
  let fixture: ComponentFixture<AppComponent>;

  beforeEach(async () => {
    await TestBed.configureTestingModule({
      declarations: [AppComponent],
    }).compileComponents();

    fixture = TestBed.createComponent(AppComponent);
    component = fixture.componentInstance;
    fixture.detectChanges();
  });

  it('should create the app', () => {
    expect(component).toBeTruthy();
  });

  it('should render title', () => {
    const compiled = fixture.nativeElement as HTMLElement;
    expect(compiled.querySelector('h1')?.textContent).toContain('Angular');
  });

  it('should increment count on button click', () => {
    const compiled = fixture.nativeElement as HTMLElement;
    const button = compiled.querySelector('button') as HTMLButtonElement;
    button.click();
    fixture.detectChanges();
    expect(component.count).toBe(1);
  });
});
--Explanation

Testing Setup
Jasmine = test framework. Karma = test runner. TestBed = Angular testing utility.
Test Structure
describe('suite', () => { it('test name', () => { expect(...).toBe(...) }) }) — nested test suites and individual test cases.
TestBed
TestBed.configureTestingModule({ declarations: [Component] }) — configure testing module. compileComponents() — compile templates. TestBed.createComponent(Component) — create test fixture.
Assertions
expect(component).toBeTruthy() — check truthy. expect(value).toBe(expected) — check equality. expect(el.textContent).toContain('text') — check DOM content.
Running Tests
ng test — run all tests in watch mode. ng test --watch=false

Components & Templates

Angular | Lesson 2

Learning Objectives

Understand Angular component: @Component with selector and template\nUse interpolation {{ }} to display data\nUse event binding (click) to handle user actions\nSeparate template to .html file with templateUrl

--Program: Angular

typescript
import { Component } from '@angular/core';

@Component({
  selector: 'app-root',
  template: `<div>
    <h1>{{ title }}</h1>
    <p>{{ message }}</p>
    <button (click)="onClick()">Klik Saya</button>
  </div>`,
})
export class AppComponent {
  title = 'Angular Components';
  message = 'Belajar data binding di Angular';

