    // new function
    num := new(int)
    *num = 100
    fmt.Println("Melalui new:", *num)

    // Nil safety
    var ptr *int
    if ptr != nil {
        fmt.Println(*ptr)
    } else {
        fmt.Println("Pointer nil, aman")
    }
}
