package main

import (
    "fmt"
    "sync"
    "time"
)

func worker(id int, wg *sync.WaitGroup) {
    defer wg.Done()
    fmt.Printf("Worker %d mulai\n", id)
    time.Sleep(100 time.Millisecond)
    fmt.Printf("Worker %d selesai\n", id)
}

type Counter struct {
    mu    sync.Mutex
    value int
}

func (c *Counter) Increment() {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.value+}

func (c *Counter) Value() int {
    c.mu.Lock()
    defer c.mu.Unlock()
    return c.value
}

func main() {
    // WaitGroup
    var wg sync.WaitGroup
    for i := 1; i <= 3; i+{
        wg.Add(1)
        go worker(i, &wg)
    }
    wg.Wait()
    fmt.Println("Semua worker selesai")

    // Mutex
    counter := Counter{}
    var wg2 sync.WaitGroup
    for i := 0; i < 1000; i+{
        wg2.Add(1)
        go func() {
            defer wg2.Done()
            counter.Increment()
        }()
    }
    wg2.Wait()
    fmt.Printf("Counter: %d (seharusnya 1000)\n", counter.Value())
}
