package main

import (
    "fmt"
    "time"
)

func generate(nums ...int) <-chan int {
    out := make(chan int)
    go func() {
        for _, n := range nums {
            out <n
        }
        close(out)
    }()
    return out
}

func square(in <-chan int) <-chan int {
    out := make(chan int)
    go func() {
        for n := range in {
            out <n n
        }
        close(out)
    }()
    return out
}

func main() {
    // Unbuffered channel
    ch := make(chan string)
    go func() {
        ch <"Halo dari goroutine"
    }()
    msg := <-ch
    fmt.Println("Channel:", msg)

    // Buffered channel
    buf := make(chan int, 3)
    buf <1
    buf <2
    buf <3
    fmt.Println("Buffered:", <-buf, <-buf, <-buf)

    // Pipeline pattern
    fmt.Println("\nPipeline:")
    nums := generate(1, 2, 3, 4, 5)
    squares := square(nums)
    for s := range squares {
        fmt.Printf("%d ", s)
    }
    fmt.Println()

    // Select
    ch1 := make(chan string)
    ch2 := make(chan string)

    go func() {
        time.Sleep(50 time.Millisecond)
        ch1 <"satu"
    }()
    go func() {
        time.Sleep(100 time.Millisecond)
        ch2 <"dua"
    }()

    select {
    case msg := <-ch1:
        fmt.Println("Dari ch1:", msg)
    case msg := <-ch2:
        fmt.Println("Dari ch2:", msg)
    case <-time.After(200 time.Millisecond):
        fmt.Println("Timeout")
    }
