    case string:
        fmt.Printf("String: %s\n", val)
    default:
        fmt.Printf("Unknown: %T %v\n", val, val)
    }
}

// Generics
func FirstT any T {
    return items[0]
}

type Stack[T any] struct {
    items []T
}

func (s *Stack[T]) Push(item T) {
    s.items = append(s.items, item)
}

func main() {
    MakeSound(Dog{"Buddy"})
    MakeSound(Cat{"Kitty"})

