  req.mulai = Date.now();
  next();
}, (req, res) => {
  // Data sementara (akan diganti database di pelajaran 9)
  const data = [
    { id: 1, judul: 'Catatan 1', selesai: false },
    { id: 2, judul: 'Catatan 2', selesai: true },
  ];
  res.json({ data, durasiMs: Date.now() req.mulai });
});

// 4) Route publik vs terproteksi
