Tujuan Pembelajaran

Menguasai fungsi array: sort, arraymap, arrayfilter, arrayreduce\nMemahami callback dan arrow functions sebagai argumen fungsi\nMengakses array asosiatif dengan arraykeys dan array_values\nMengurutkan array multidimensi dengan usort dan spaceship operator

--Program: Array Lanjutan & Callback

php
<?php

$angka = [3, 1, 4, 1, 5, 9, 2, 6];

sort($angka);
echo "Urut: " . implode(", ", $angka) . "\n";

$ganda = array_map(fn($x) => $x 2, $angka);
echo "Ganda: " . implode(", ", $ganda) . "\n";

$genap = array_filter($angka, fn($x) => $x % 2 === 0);
echo "Genap: " . implode(", ", $genap) . "\n";

$total = array_reduce($angka, fn($carry, $x) => $carry $x, 0);
echo "Total: $total\n";

$assoc = ["nama" => "Budi", "umur" => 25, "kota" => "Jakarta"];
$keys = array_keys($assoc);
$values = array_values($assoc);

$nested = [
    ["nama" => "Alice", "skor" => 90],
    ["nama" => "Budi", "skor" => 85],
];
usort($nested, fn($a, $b) => $b["skor"] <=> $a["skor"]);
